<?php require_once __DIR__.'/professional_assets/bootstrap_portal.php'; require_role(['admin','worker','doctor']);$con->query("CREATE TABLE IF NOT EXISTS radiology_requests(id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,doctor_id INT DEFAULT 0,modality VARCHAR(60) NOT NULL,body_part VARCHAR(100) DEFAULT '',report TEXT,status VARCHAR(30) DEFAULT 'Pending',requested_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$s=$con->prepare("INSERT INTO radiology_requests(patient_id,doctor_id,modality,body_part) VALUES(?,?,?,?)");$p=(int)$_POST['patient_id'];$d=(int)$_POST['doctor_id'];$m=$_POST['modality'];$b=trim($_POST['body_part']);$s->bind_param('iiss',$p,$d,$m,$b);if($s->execute())$msg='Radiology request created.';}$patients=$con->query("SELECT patientid,patientname FROM patient ORDER BY patientname");$rows=$con->query("SELECT r.*,p.patientname FROM radiology_requests r JOIN patient p ON p.patientid=r.patient_id ORDER BY r.id DESC LIMIT 100");?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="professional_assets/app.css"><link rel="stylesheet" href="professional_assets/theme.css.php"><title>Radiology</title></head><body class="module-body"><div class="module-wrap"><div class="module-head"><div><span class="eyebrow">RADIOLOGY</span><h1>Radiology</h1><p>X-ray, ultrasound, CT, MRI, requests and reports.</p></div></div><?php if($msg):?><div class="success"><?=$msg?></div><?php endif;?><div class="panel"><h2>New request</h2><form method="post" class="form-grid"><label>Patient<select name="patient_id" required><?php while($p=$patients->fetch_assoc()):?><option value="<?=$p['patientid']?>"><?=esc($p['patientname'])?></option><?php endwhile;?></select></label><label>Doctor ID<input type="number" name="doctor_id" min="0"></label><label>Modality<select name="modality"><option>X-Ray</option><option>Ultrasound</option><option>CT</option><option>MRI</option></select></label><label>Body part<input name="body_part"></label><button class="primary-btn">Create request</button></form></div><div class="panel"><h2>Radiology requests</h2><div class="table-wrap"><table><thead><tr><th>Patient</th><th>Modality</th><th>Body part</th><th>Status</th><th>Report</th><th>Date</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()):?><tr><td><?=esc($r['patientname'])?></td><td><?=esc($r['modality'])?></td><td><?=esc($r['body_part'])?></td><td><?=esc($r['status'])?></td><td><?=esc($r['report'])?></td><td><?=esc($r['requested_at'])?></td></tr><?php endwhile;?></tbody></table></div></div></div></body></html>
